func minWindow(_ s: String, _ t: String) -> String {
    let a = Array(s)
    var need: [Character: Int] = [:]
    for c in t { need[c, default: 0] += 1 }
    var missing = t.count, left = 0, best = (start: 0, len: Int.max)
    for right in a.indices {
        if need[a[right], default: 0] > 0 { missing -= 1 }
        need[a[right], default: 0] -= 1
        while missing == 0 {
            if right - left + 1 < best.len { best = (left, right - left + 1) }
            need[a[left], default: 0] += 1
            if need[a[left]]! > 0 { missing += 1 }
            left += 1
        }
    }
    return best.len == Int.max ? "" : String(a[best.start..<best.start + best.len])
}
